// === Tab: mySketch ===
// by SamuelYAN
// more works //
// https://twitter.com/SamuelAnn0924
// https://www.instagram.com/samuel_yan_1990/

// reference: https://gorillasun.de/blog/Smooth-Curves-with-Perlin-Noise-and-Recreating-the-Unknown-Pleasures-Album-Cover-in-P5

var seed = Math.random() * 9999;
var xOff, yOff, dir, plus, wave_h,t,p;
var color1, color2;
//new color pallete
let colors0 = "4596c7-6d8370-e45240-21d3a4-3303f9".split("-").map((a) => "#" + a);
let colors02 = "4596c7-6d8370-e45240-21d3a4-3303f9".split("-").map((a) => "#" + a +"1a");
let colors1 = "5d565c-b41a1d-c0dee4-edb136-e07958".split("-").map((a) => "#" + a);
let colors12 = "5d565c-b41a1d-c0dee4-edb136-e07958".split("-").map((a) => "#" + a +"1a");
let colors2 = "7382ce-9fb7f4-12177d-9bb5e9-7486af".split("-").map((a) => "#" + a);
let colors22 = "7382ce-9fb7f4-12177d-9bb5e9-7486af".split("-").map((a) => "#" + a +"1a");
let colors3 = "1b1b1b-292929-f3f3f3-222222-ff0000".split("-").map((a) => "#" + a);
let colors32 = "1b1b1b-292929-f3f3f3-222222-ff0000".split("-").map((a) => "#" + a +"1a");
let colors4 = "eda492-d59c95-af3918-d9b6b5-853532".split("-").map((a) => "#" + a);
let colors42 = "eda492-d59c95-af3918-d9b6b5-853532".split("-").map((a) => "#" + a +"1a");
let colors5 = "f86fcd-97d183-240ce8-b0e298-7f37e8".split("-").map((a) => "#" + a);
let colors52 = "f86fcd-97d183-240ce8-b0e298-7f37e8".split("-").map((a) => "#" + a +"1a");
let colorbg = "ffffff".split("-").map((a) => "#" + a);
let colorbg2 = "ffffff1a".split("-").map((a) => "#" + a);
var grad;

function setup() {
	randomSeed(seed);
	createCanvas(windowWidth,windowHeight);
	background(colorbg2);
	// pixelDensity(5);
	color1 = random([colors0, colors1, colors2, colors3, colors4, colors5]);
	color2 = colorbg2;
	xOff = 0;
	yOff = 0;
	dir = 1;
	plus = 0.5;
	wave_h =100;
	t =0;
	makeFilter();
}

function draw() {
	randomSeed(seed);
	// background(colorbg2);
	noStroke();
	let mountain_h = height / int(random(30, 50));
	for (let n = 0; n < height; n += random(mountain_h/2,mountain_h)) {
		push();
		translate(0, height-n);
		grad = drawingContext.createLinearGradient(0, -mountain_h, 0, mountain_h);
		grad.addColorStop(0, random(color1));
		grad.addColorStop(1, random(color2));
		drawingContext.fillStyle = grad;
		for (let i = xOff; i < width - xOff; i += 10) {
			p = random(-1, 1);
			circle(i, cos(i+t) * random(yOff)*p,random(15))
		}
		pop();
	}

	if (dir == 1) {
		if(yOff < wave_h){ dir = 1;}
		else if(yOff >= wave_h){dir = -1;plus = random(0.1);}
	} 
	else if (dir == -1) {
		if(yOff > 0){ dir = -1;}
		else if(yOff <= 0){dir = 1;plus = random(0.1);}
	} 

	yOff += plus * dir;
	t += 0.1;
	p += 1;
	image(overAllTexture, 0, 0);
}

function makeFilter() {
	// noiseのフィルターをつくる
	colorMode(HSB, 360, 100, 100, 100);
	drawingContext.shadowColor = color(0, 0, 5, 95);
	overAllTexture = createGraphics(windowWidth, windowHeight);
	overAllTexture.loadPixels();
	for (var i = 0; i < width; i++) {
		for (var j = 0; j < height; j++) {
			overAllTexture.set(
				i,
				j,
				color(
					0,
					0,
					99,
					noise(i / 3, j / 3, (i * j) / 50) * random(1, 5)
				)
			);
		}
	}
	overAllTexture.updatePixels();
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("GENUARY 2022_0120_a sea of Circles", "png");
	}
}

